    29	    return state.items.filter((ticket) => ticket.status !== 'closed')
    30	  },
    31	  sortedTickets(state, getters) {
    32	    return getters.openTickets.slice().sort(comparePriority)
    33	  },
    34	  breachedTickets(state) {
    35	    const now = Date.now()
    36	    return state.items.filter((ticket) => isBreached(ticket, now))
    37	  },
    38	  ticketById: (state) => (id) => state.items.find((ticket) => ticket.id === id)
    39	}
