    42	  SET_LOADING(state, loading) {
    43	    state.loading = loading
    44	  },
    45	  SET_TICKETS(state, { items, total }) {
    46	    state.items = items
    47	    state.total = total
    48	  },
    49	  SET_CURRENT(state, ticket) {
    50	    state.current = ticket
    51	  },
    52	  SET_REPLIES(state, replies) {
    53	    state.replies = replies
    54	  },
    55	  ADD_REPLY(state, reply) {
    56	    state.replies.push(reply)
    57	  },
    58	  SET_FILTERS(state, filters) {
    59	    state.filters = Object.assign({}, state.filters, filters)
    60	  },
    61	  UPDATE_TICKET(state, ticket) {
    62	    const index = state.items.findIndex((item) => item.id === ticket.id)
    63	    if (index !== -1) {
    64	      state.items.splice(index, 1, ticket)
    65	    }
    66	    if (state.current && state.current.id === ticket.id) {
    67	      state.current = ticket
    68	    }
    69	  }
    70	}
