    10	<script>
    11	import { paginationMixin } from '@/mixins/paginationMixin'
    12	
    13	// Base for paged list views. Views extend it, override fetchPage(), and wrap
    14	// their loader in load() so rows, totals and the loading flag stay in sync.
    15	export default {
    16	  name: 'BaseListView',
    17	  mixins: [paginationMixin],
    18	  props: {
    19	    title: {
    20	      type: String,
    21	      default: ''
    22	    },
    23	    emptyText: {
    24	      type: String,
    25	      default: 'Nothing to show'
    26	    }
    27	  },
    28	  data() {
    29	    return {
    30	      rows: [],
    31	      loading: false,
    32	      loadError: null
    33	    }
    34	  },
    35	  mounted() {
    36	    this.goToPage(1)
    37	  },
    38	  methods: {
    39	    fetchPage() {
    40	      return Promise.resolve()
    41	    },
    42	    async load(loader) {
    43	      this.loading = true
    44	      this.loadError = null
    45	      try {
    46	        const result = await loader()
    47	        this.rows = result.items
    48	        this.setTotal(result.total)
    49	        return result
    50	      } catch (error) {
    51	        this.loadError = error
    52	        throw error
    53	      } finally {
    54	        this.loading = false
    55	      }
    56	    }
    57	  }
    58	}
    59	</script>
