import React from 'react'

const PAGE_SIZES = [10, 25, 50, 100]

// Shared paging state for list views. A component that extends this base
// implements fetchPage() and calls goToPage() when its filters change.
export class PaginatedComponent extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      page: 1,
      pageSize: props.initialPageSize,
      total: 0
    }
    this.goToPage = this.goToPage.bind(this)
    this.nextPage = this.nextPage.bind(this)
    this.prevPage = this.prevPage.bind(this)
  }

  get totalPages() {
    return Math.max(1, Math.ceil(this.state.total / this.state.pageSize))
  }

  get hasNextPage() {
    return this.state.page < this.totalPages
  }

  get hasPrevPage() {
    return this.state.page > 1
  }

  componentDidUpdate(prevProps, prevState) {
    if (prevState.pageSize !== this.state.pageSize) {
      this.pageSize()
    }
  }

  pageSize() {
    this.goToPage(1)
  }

  async goToPage(page) {
    await new Promise((resolve) => this.setState({ page: Math.min(Math.max(1, page), this.totalPages) }, resolve))
    return this.fetchPage()
  }

  nextPage() {
    if (this.hasNextPage) {
      return this.goToPage(this.state.page + 1)
    }
    return Promise.resolve()
  }

  prevPage() {
    if (this.hasPrevPage) {
      return this.goToPage(this.state.page - 1)
    }
    return Promise.resolve()
  }

  setTotal(total) {
    this.setState({ total })
  }
}

PaginatedComponent.defaultProps = {
  initialPageSize: 25
}

PaginatedComponent.propTypes = {
  initialPageSize: (props) => (PAGE_SIZES.indexOf(props.initialPageSize) !== -1 ? null : new Error('initialPageSize must be one of ' + PAGE_SIZES.join(', ')))
}

export default PaginatedComponent
