import React from 'react'
import { EventBus } from '../eventBus'
import { isBreached, minutesRemaining } from '../utils/sla'

const TICK_MS = 30000

// Keeps `now` fresh so SLA countdowns re-render, and announces a breach once.
// The subclass provides a `slaTicket` getter.
export class SlaTimerComponent extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      now: Date.now(),
      breachAnnounced: false
    }
    this.slaInterval = null
    this.tickSla = this.tickSla.bind(this)
  }

  componentDidMount() {
    this.startSlaTimer()
  }

  componentWillUnmount() {
    this.stopSlaTimer()
  }

  startSlaTimer() {
    this.stopSlaTimer()
    this.slaInterval = setInterval(this.tickSla, TICK_MS)
  }

  stopSlaTimer() {
    if (this.slaInterval) {
      clearInterval(this.slaInterval)
      this.slaInterval = null
    }
  }

  tickSla() {
    const now = Date.now()
    this.setState({ now })
    if (this.slaTicket && !this.state.breachAnnounced && isBreached(this.slaTicket, now)) {
      this.setState({ breachAnnounced: true })
      EventBus.emit('sla:breached', this.slaTicket.id)
    }
  }

  slaMinutesLeft(ticket) {
    return minutesRemaining(ticket, this.state.now)
  }
}

