export class FormValidationComponent extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      errors: {}
    }
  }

  get hasErrors() {
    return Object.keys(this.state.errors).length > 0
  }

  setError(field, message) {
    this.setState((previous) => ({ errors: Object.assign({}, previous.errors, { [field]: message }) }))
  }

  clearErrors() {
    this.setState({ errors: {} })
  }

  validateRequired(field, value, label) {
    if (isBlank(value)) {
      this.setError(field, label + ' is required')
      return false
    }
    return true
  }

  validateEmail(field, value) {
    if (!isEmail(value)) {
      this.setError(field, 'Enter a valid email address')
      return false
    }
    return true
  }

  validateMaxLength(field, value, max) {
    if (exceedsLength(value, max)) {
      this.setError(field, 'Must be ' + max + ' characters or fewer')
      return false
    }
    return true
  }
}

