import { comparePriority } from '../../utils/priority'
import { isBreached } from '../../utils/sla'
import { push } from './notifications'

const NAMESPACE = 'tickets/'

const state = () => ({
  items: [],
  total: 0,
  current: null,
  replies: [],
  loading: false,
  filters: {
    status: 'open',
    priority: '',
    assignee: '',
    query: ''
  }
})

export function openTickets(state) {
  return state.items.filter((ticket) => ticket.status !== 'closed')
}

export function sortedTickets(state) {
  return openTickets(state).slice().sort(comparePriority)
}

export function breachedTickets(state) {
  const now = Date.now()
  return state.items.filter((ticket) => isBreached(ticket, now))
}

export const ticketById = (state) => (id) => state.items.find((ticket) => ticket.id === id)

export const mutations = {
  SET_LOADING(state, loading) {
    return Object.assign({}, state, { loading })
  },
  SET_TICKETS(state, { items, total }) {
    return Object.assign({}, state, { items, total })
  },
  SET_CURRENT(state, ticket) {
    return Object.assign({}, state, { current: ticket })
  },
  SET_REPLIES(state, replies) {
    return Object.assign({}, state, { replies })
  },
  ADD_REPLY(state, reply) {
    return Object.assign({}, state, { replies: state.replies.concat(reply) })
  },
  SET_FILTERS(state, filters) {
    return Object.assign({}, state, { filters: Object.assign({}, state.filters, filters) })
  },
  UPDATE_TICKET(state, ticket) {
    const items = state.items.map((item) => (item.id === ticket.id ? ticket : item))
    const current = state.current && state.current.id === ticket.id ? ticket : state.current
    return Object.assign({}, state, { items, current })
  }
}

export const fetchTickets = (params) => async (dispatch, getState) => {
  dispatch({ type: 'tickets/SET_LOADING', payload: true })
  try {
    const result = await fetchTicketList(Object.assign({}, getState().tickets.filters, params))
    dispatch({ type: 'tickets/SET_TICKETS', payload: result })
    return result
  } finally {
    dispatch({ type: 'tickets/SET_LOADING', payload: false })
  }
}

export const fetchTicket = (id) => async (dispatch) => {
  const ticket = await fetchTicketById(id)
  dispatch({ type: 'tickets/SET_CURRENT', payload: ticket })
  await dispatch(fetchReplies(id))
  return ticket
}

export const fetchReplies = (ticketId) => async (dispatch) => {
  dispatch({ type: 'tickets/SET_REPLIES', payload: await fetchTicketReplies(ticketId) })
}

export const postReply = ({ ticketId, body, internal }) => async (dispatch) => {
  const reply = await createReply(ticketId, body, internal)
  dispatch({ type: 'tickets/ADD_REPLY', payload: reply })
  dispatch(push({ level: 'success', text: 'Reply sent' }))
  return reply
}

export const updateStatus = ({ id, status }) => async (dispatch) => {
  const ticket = await updateTicketStatus(id, status)
  dispatch({ type: 'tickets/UPDATE_TICKET', payload: ticket })
  EventBus.emit('ticket:updated', { ticketId: id })
  return ticket
}

export const assignTicket = ({ id, agentId }) => async (dispatch) => {
  const ticket = await assignTicketToAgent(id, agentId)
  dispatch({ type: 'tickets/UPDATE_TICKET', payload: ticket })
  return ticket
}

export const applyFilters = (filters) => (dispatch) => {
  dispatch({ type: 'tickets/SET_FILTERS', payload: filters })
  return dispatch(fetchTickets({ page: 1 }))
}

export default function ticketsReducer(current = state(), action) {
  const mutation = action.type.indexOf(NAMESPACE) === 0 ? mutations[action.type.slice(NAMESPACE.length)] : null
  return mutation ? mutation(current, action.payload) : current
}
