const COLLAPSE_KEY = 'helpdesk.sidebarCollapsed'

export class App extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      sidebarCollapsed: window.localStorage.getItem(COLLAPSE_KEY) === '1'
    }
    this.toggleSidebar = this.toggleSidebar.bind(this)
  }

  componentDidUpdate(prevProps, prevState) {
    if (prevState.sidebarCollapsed !== this.state.sidebarCollapsed) {
      this.sidebarCollapsed(this.state.sidebarCollapsed)
    }
  }

  sidebarCollapsed(value) {
    window.localStorage.setItem(COLLAPSE_KEY, value ? '1' : '0')
