            <AppSidebar collapsed={this.state.sidebarCollapsed} />
          </React.Fragment>
        )}
        <main id="main-content">
          <Suspense fallback={null}>
            <Switch>
              {routes.map((route) => (
                <Route
                  key={route.name}
                  path={route.path}
                  exact={route.exact}
                  render={(routeProps) => {
                    const View = route.component
                    return <View {...routeProps} {...(route.props ? routeProps.match.params : {})} />
                  }}
                />
              ))}
            </Switch>
          </Suspense>
        </main>
        {this.props.isAuthenticated && <NotificationTray />}
      </div>
    )
  }
}

function mapStateToProps(state) {
  return {
    isAuthenticated: isAuthenticated(state.auth)
  }
}

export default connect(mapStateToProps)(App)
