  render() {
    const { type, variant, disabled, busy, children, onClick, ...rest } = this.props
    return (
      <button
        {...rest}
        type={type}
        className={['btn', 'btn--' + variant, busy ? 'btn--busy' : ''].join(' ')}
        disabled={disabled || busy}
        onClick={this.handleClick}
      >
        {busy && <BaseSpinner size="small" />}
        {children}
      </button>
    )
  }
}

BaseButton.defaultProps = {
  variant: 'primary',
  type: 'button',
  disabled: false,
  busy: false,
  onClick: () => {}
}

