let uid = 0

export default class BaseModal extends React.Component {
  constructor(props) {
    super(props)
    this.uid = ++uid
    this.close = this.close.bind(this)
    this.onKeydown = this.onKeydown.bind(this)
  }

  get titleId() {
    return 'modal-title-' + this.uid
  }

  componentDidMount() {
    document.addEventListener('keydown', this.onKeydown)
  }

  componentDidUpdate(prevProps) {
    if (prevProps.open !== this.props.open) {
      this.open(this.props.open)
    }
  }

  componentWillUnmount() {
    document.removeEventListener('keydown', this.onKeydown)
    document.body.classList.remove('has-modal')
  }

  open(isOpen) {
    document.body.classList.toggle('has-modal', isOpen)
  }

  close() {
    this.props.onClose()
  }

  onKeydown(event) {
    if (this.props.open && event.key === 'Escape') {
      this.close()
    }
  }

  render() {
    if (!this.props.open) {
      return null
    }
    return (
      <div className="modal-backdrop" onClick={(event) => { if (event.target === event.currentTarget) this.close() }}>
        <div className="modal" role="dialog" aria-modal="true" aria-labelledby={this.titleId}>
          <header className="modal__header">
            <h2 id={this.titleId}>{this.props.title}</h2>
            <BaseButton variant="link" aria-label="Close" onClick={this.close}>x</BaseButton>
          </header>
          <div className="modal__body">
            {this.props.children}
          </div>
          {this.props.footer && (
            <footer className="modal__footer">
              {this.props.footer}
            </footer>
          )}
        </div>
      </div>
    )
  }
}

BaseModal.defaultProps = {
  open: false,
  title: '',
  footer: null,
  onClose: () => {}
}
