import React from 'react'
import BaseSpinner from './BaseSpinner'

const VARIANTS = ['primary', 'secondary', 'danger', 'link']

export default class BaseButton extends React.Component {
  constructor(props) {
    super(props)
    this.handleClick = this.handleClick.bind(this)
  }

  handleClick(event) {
    if (!this.props.disabled && !this.props.busy) {
      this.props.onClick(event)
    }
  }

  render() {
    const { type, variant, disabled, busy, children, onClick, ...rest } = this.props
    return (
      <button
        {...rest}
        type={type}
        className={['btn', 'btn--' + variant, busy ? 'btn--busy' : ''].join(' ')}
        disabled={disabled || busy}
        onClick={this.handleClick}
      >
        {busy && <BaseSpinner size="small" />}
        {children}
      </button>
    )
  }
}

