import React from 'react'
import { PaginatedComponent } from '@/mixins/paginationMixin'
import BaseSpinner from '@/components/base/BaseSpinner'

// Base for paged list views. Views extend it, override fetchPage(), and wrap
// their loader in load() so rows, totals and the loading flag stay in sync.
export default class BaseListView extends PaginatedComponent {
  constructor(props) {
    super(props)
    this.state = Object.assign({}, this.state, {
      rows: [],
      loading: false,
      loadError: null
    })
  }

  componentDidMount() {
    this.goToPage(1)
  }

  fetchPage() {
    return Promise.resolve()
  }

  async load(loader) {
    this.setState({ loading: true, loadError: null })
    try {
      const result = await loader()
      this.setState({ rows: result.items })
      this.setTotal(result.total)
      return result
    } catch (error) {
      this.setState({ loadError: error })
      throw error
    } finally {
      this.setState({ loading: false })
    }
  }

  render() {
    const { title, emptyText, children } = this.props
    const { loading, rows } = this.state
    return (
      <section className="list-view">
        <h1 className="list-view__title">{title}</h1>
        {loading ? (
          <BaseSpinner />
        ) : !rows.length ? (
          <p className="list-view__empty">{emptyText}</p>
        ) : (
          children({ rows })
        )}
      </section>
    )
  }
}

BaseListView.defaultProps = Object.assign({}, PaginatedComponent.defaultProps, {
  title: '',
  emptyText: 'Nothing to show',
  children: () => null
})
