import React from 'react'
import { connect } from 'react-redux'
import { bindActionCreators } from 'redux'
import { EventBus } from '../../eventBus'
import BaseButton from '../base/BaseButton'
import { unreadCount, push } from '../../store/modules/notifications'
import { timeAgo } from '../../utils/date'

export class NotificationTray extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      open: false
    }
    this.toggle = this.toggle.bind(this)
    this.onAssigned = this.onAssigned.bind(this)
    this.onBreached = this.onBreached.bind(this)
  }

  componentDidMount() {
    EventBus.on('ticket:assigned', this.onAssigned)
    EventBus.on('sla:breached', this.onBreached)
  }

  componentWillUnmount() {
    EventBus.off('ticket:assigned', this.onAssigned)
    EventBus.off('sla:breached', this.onBreached)
  }

  toggle() {
    const open = !this.state.open
    this.setState({ open })
    if (open) {
      this.props.MARK_ALL_READ()
    }
  }

  onAssigned(payload) {
    this.props.push({ level: 'info', text: 'Ticket #' + payload.ticketId + ' was assigned' })
  }

  onBreached(ticketId) {
    this.props.push({ level: 'danger', text: 'Ticket #' + ticketId + ' breached its SLA' })
  }

  render() {
    const { open } = this.state
    const { items } = this.props
    return (
      <aside className={'notification-tray' + (open ? ' notification-tray--open' : '')}>
        <BaseButton variant="link" onClick={this.toggle}>Notifications ({this.props.unreadCount})</BaseButton>
        {open && (
          <ul id="notification-list">
            {items.map((item) => (
              <li key={item.id} className={'notification--' + item.level}>
                <span>{item.text}</span>
                <small>{timeAgo(item.createdAt)}</small>
                <BaseButton variant="link" aria-label="Dismiss" onClick={() => this.props.DISMISS(item.id)}>x</BaseButton>
              </li>
            ))}
          </ul>
        )}
      </aside>
    )
  }
}

function mapStateToProps(state) {
  return {
    items: state.notifications.items,
    unreadCount: unreadCount(state.notifications)
  }
}

function mapDispatchToProps(dispatch) {
  return Object.assign(
    {
      DISMISS: (id) => dispatch({ type: 'notifications/DISMISS', payload: id }),
      MARK_ALL_READ: () => dispatch({ type: 'notifications/MARK_ALL_READ' })
    },
    bindActionCreators({ push }, dispatch)
  )
}

export default connect(mapStateToProps, mapDispatchToProps)(NotificationTray)
