import React from 'react'
import { connect } from 'react-redux'
import { EventBus } from '@/eventBus'
import BaseButton from '@/components/base/BaseButton'
import { availableAgents, loadAgents } from '@/store/modules/agents'
import { assignTicket } from '@/store/modules/tickets'

export class AgentSelect extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      agentId: '',
      saving: false
    }
    this.assign = this.assign.bind(this)
  }

  get inputId() {
    return 'agent-select-' + this.props.ticketId
  }

  componentDidMount() {
    this.props.dispatch(loadAgents())
  }

  async assign() {
    this.setState({ saving: true })
    try {
      await this.props.dispatch(assignTicket({ id: this.props.ticketId, agentId: this.state.agentId }))
      EventBus.emit('ticket:assigned', { ticketId: this.props.ticketId, agentId: this.state.agentId })
      this.props.onAssigned(this.state.agentId)
    } finally {
      this.setState({ saving: false })
    }
  }

  render() {
    const { agentId, saving } = this.state
    return (
      <div className="agent-select">
        <label htmlFor={this.inputId}>Assign to</label>
        <select id={this.inputId} value={agentId} disabled={saving} onChange={(event) => this.setState({ agentId: event.target.value })}>
          <option disabled value="">Choose an agent</option>
          {this.props.availableAgents.map((agent) => (
            <option key={agent.id} value={agent.id}>
              {agent.name}
            </option>
          ))}
        </select>
        <BaseButton busy={saving} disabled={!agentId} onClick={this.assign}>Assign</BaseButton>
      </div>
