import React from 'react'
import { PRIORITIES, priorityLabel } from '../../utils/priority'
import BaseButton from '../base/BaseButton'

const DEFAULT_FILTERS = {
  status: 'open',
  priority: '',
  assignee: '',
  query: ''
}

let uid = 0

export default class TicketFilters extends React.Component {
  constructor(props) {
    super(props)
    this.uid = ++uid
    this.state = {
      local: Object.assign({}, props.value),
      priorities: PRIORITIES,
      statusOptions: [
        { value: 'open', label: 'Open' },
        { value: 'pending', label: 'Pending' },
        { value: 'solved', label: 'Solved' },
        { value: 'closed', label: 'Closed' }
      ]
    }
    this.reset = this.reset.bind(this)
  }

  get priorityInputId() {
    return 'filter-priority-' + this.uid
  }

  get isDirty() {
    return JSON.stringify(this.state.local) !== JSON.stringify(this.props.value)
  }

  componentDidUpdate(prevProps) {
    if (JSON.stringify(prevProps.value) !== JSON.stringify(this.props.value)) {
      this.value(this.props.value)
    }
  }

  value(next) {
    this.setState({ local: Object.assign({}, next) })
  }

  apply() {
    this.props.onChange(Object.assign({}, this.state.local))
  }

  reset() {
    this.setState({ local: Object.assign({}, DEFAULT_FILTERS) }, () => this.apply())
  }

  render() {
    const { local, priorities, statusOptions } = this.state
    const setLocal = (field, value) => this.setState({ local: Object.assign({}, local, { [field]: value }) })
    return (
      <form id="ticket-filters" className="ticket-filters" onSubmit={(event) => { event.preventDefault(); this.apply() }}>
        <label htmlFor="filter-status">Status</label>
        <select id="filter-status" value={local.status} onChange={(event) => setLocal('status', event.target.value)}>
          {statusOptions.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
        <label htmlFor={this.priorityInputId}>Priority</label>
        <select id={this.priorityInputId} value={local.priority} onChange={(event) => setLocal('priority', event.target.value)}>
          <option value="">Any</option>
          {priorities.map((priority) => (
            <option key={priority} value={priority}>
              {priorityLabel(priority)}
            </option>
          ))}
        </select>
        <input
          id="filter-query"
          value={local.query}
          onChange={(event) => setLocal('query', event.target.value.trim())}
          type="search"
          placeholder="Search subject or customer"
          onKeyUp={(event) => { if (event.key === 'Escape') this.reset() }}
        />
        <BaseButton type="submit" disabled={!this.isDirty}>Apply</BaseButton>
        <BaseButton variant="link" onClick={this.reset}>Reset</BaseButton>
      </form>
    )
  }
}

TicketFilters.defaultProps = {
  onChange: () => {}
}
