import React from 'react'
import { connect } from 'react-redux'
import CannedResponsePicker from './CannedResponsePicker'
import BaseButton from '../base/BaseButton'
import { FormValidationComponent } from '@/mixins/formValidationMixin'
import { EventBus } from '../../eventBus'
import { postReply } from '@/store/modules/tickets'

const MAX_REPLY_LENGTH = 10000

export class TicketReplyForm extends FormValidationComponent {
  constructor(props) {
    super(props)
    this.state = Object.assign({}, this.state, {
      body: '',
      internal: false,
      sending: false,
      showCanned: false
    })
    this.toggleCanned = this.toggleCanned.bind(this)
    this.insertCanned = this.insertCanned.bind(this)
  }

  validate() {
    this.clearErrors()
    return this.validateRequired('body', this.state.body, 'Reply') &&
      this.validateMaxLength('body', this.state.body, MAX_REPLY_LENGTH)
  }

  toggleCanned() {
    this.setState((previous) => ({ showCanned: !previous.showCanned }))
  }

  insertCanned(text) {
    this.setState((previous) => ({ body: previous.body ? previous.body + '\n\n' + text : text, showCanned: false }))
  }

  async submitReply() {
    if (!this.validate()) {
      return
    }
    this.setState({ sending: true })
    try {
      const reply = await this.props.dispatch(postReply({
        ticketId: this.props.ticketId,
        body: this.state.body,
        internal: this.state.internal
      }))
      EventBus.emit('reply:posted', { ticketId: this.props.ticketId, reply })
      this.props.onReplySent(reply)
      this.setState({ body: '' })
    } finally {
      this.setState({ sending: false })
    }
  }

  render() {
    const { body, internal, sending, showCanned, errors } = this.state
    return (
      <form className="reply-form" onSubmit={(event) => { event.preventDefault(); this.submitReply() }}>
        <h3 id="reply-form-title">Reply</h3>
        {showCanned && <CannedResponsePicker onInsert={this.insertCanned} onClose={() => this.setState({ showCanned: false })} />}
        <textarea
          id="reply-body"
          value={body}
          onChange={(event) => this.setState({ body: event.target.value })}
          rows="6"
          aria-labelledby="reply-form-title"
          className={errors.body ? 'has-error' : ''}
          onKeyDown={(event) => { if (event.ctrlKey && event.key === 'Enter') this.submitReply() }}
        />
        {errors.body && <p className="field-error">{errors.body}</p>}
        <label className="reply-form__internal">
          <input checked={internal} onChange={(event) => this.setState({ internal: event.target.checked })} type="checkbox" /> Internal note
        </label>
        <div className="reply-form__actions">
          <BaseButton variant="secondary" onClick={this.toggleCanned}>Canned responses</BaseButton>
          <BaseButton type="submit" busy={sending}>Send reply</BaseButton>
        </div>
      </form>
    )
  }
}

TicketReplyForm.defaultProps = {
  onReplySent: () => {}
}

export default connect()(TicketReplyForm)
