import React from 'react'
import { connect } from 'react-redux'
import StatCard from '@/components/reports/StatCard'
import TicketList from '@/components/tickets/TicketList'
import BaseButton from '@/components/base/BaseButton'
import { EventBus } from '@/eventBus'
import { slaStatus } from '@/utils/sla'
import { openTickets, breachedTickets, assignTicket } from '@/store/modules/tickets'

export class Dashboard extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      claiming: false,
      lastClaimedId: null,
      assignedToday: 0,
      breachCount: 0
    }
    this.refreshStats = this.refreshStats.bind(this)
    this.onBreach = this.onBreach.bind(this)
    this.claimNext = this.claimNext.bind(this)
  }

  get atRiskCount() {
    return this.props.openTickets.filter((ticket) => slaStatus(ticket) === 'at-risk').length
  }

  get stats() {
    return [
      { key: 'open', label: 'Open', value: this.props.openTickets.length },
      { key: 'at-risk', label: 'At risk', value: this.atRiskCount, tone: 'warning' },
      { key: 'breached', label: 'Breached', value: this.props.breachedTickets.length + this.state.breachCount, tone: 'danger' },
      { key: 'assigned', label: 'Assigned today', value: this.state.assignedToday, tone: 'success' }
    ]
  }

  componentDidMount() {
    EventBus.on('ticket:assigned', this.refreshStats)
    EventBus.on('sla:breached', this.onBreach)
  }

  componentWillUnmount() {
    EventBus.off('ticket:assigned', this.refreshStats)
    EventBus.off('sla:breached', this.onBreach)
  }

  refreshStats() {
    this.setState((previous) => ({ assignedToday: previous.assignedToday + 1 }))
  }

  onBreach() {
    this.setState((previous) => ({ breachCount: previous.breachCount + 1 }))
  }

  async claimNext() {
    const next = this.props.openTickets.find((ticket) => !ticket.assigneeId)
    if (!next) {
      return
    }
    this.setState({ claiming: true })
    try {
      await this.props.dispatch(assignTicket({ id: next.id, agentId: this.props.user.id }))
      this.setState({ lastClaimedId: next.id })
      EventBus.emit('ticket:assigned', { ticketId: next.id, agentId: this.props.user.id })
    } finally {
      this.setState({ claiming: false })
    }
  }

  render() {
    return (
      <div id="dashboard" className="dashboard">
        <section className="dashboard__stats">
          {this.stats.map((stat) => (
            <StatCard
              key={stat.key}
              label={stat.label}
              value={stat.value}
              tone={stat.tone}
            />
          ))}
        </section>
        <section className="dashboard__queue">
          <header className="dashboard__queue-header">
            <h2>My queue</h2>
            <BaseButton busy={this.state.claiming} onClick={this.claimNext}>Claim next ticket</BaseButton>
          </header>
          <TicketList selectedId={this.state.lastClaimedId} autoRefresh={false} />
        </section>
      </div>
    )
  }
}

function mapStateToProps(state) {
  return {
    user: state.auth.user,
    openTickets: openTickets(state.tickets),
    breachedTickets: breachedTickets(state.tickets)
  }
}

