import React from 'react'
import { shallow } from 'enzyme'
import { PaginatedComponent } from '@/mixins/paginationMixin'

function mountPaged(total) {
  class Paged extends PaginatedComponent {
    constructor(props) {
      super(props)
      this.fetched = []
    }

    componentDidMount() {
      this.setTotal(total)
    }

    fetchPage() {
      this.fetched.push(this.state.page)
      return Promise.resolve()
    }

    render() {
      return <div />
    }
  }
  return shallow(<Paged />)
}

describe('paginationMixin', () => {
  it('computes the page count from the total', () => {
    const wrapper = mountPaged(120)
    expect(wrapper.instance().totalPages).toBe(5)
  })

  it('nextPage advances and fetches', async () => {
    const wrapper = mountPaged(60)
    await wrapper.instance().nextPage()
    expect(wrapper.state('page')).toBe(2)
    expect(wrapper.instance().fetched).toEqual([2])
  })

  it('goToPage clamps to the last page', async () => {
    const wrapper = mountPaged(30)
    await wrapper.instance().goToPage(9)
    expect(wrapper.state('page')).toBe(2)
  })
})
